class ConnectorRetryPolicyPartial(TypedDict, total=False):
    """Retry behaviour for the CONNECTOR CALLS a workflow makes (packages/core/src/retry-policy.ts) — not the workflow-run retry policy on CreateWorkflowRequest, which uses initialIntervalMs/backoffCoefficient/maximumIntervalMs. Every field is optional because a stored value is one PARTIAL layer merged field-by-field over the one below it: action override > workflow-connector override > connector row > platform default. A caller that only wants more attempts sends { maxAttempts: 5 } and inherits the rest."""
    enabled: bool
    maxAttempts: int  # Total attempts INCLUDING the first. 1 = no retry.
    initialDelayMs: int
    backoffMultiplier: float
    maxDelayMs: int  # Ceiling for any single backoff.
    maxTotalDelayMs: int  # Ceiling for all backoffs combined — the real guard on how long one call can hold a connector-concurrency slot while sleeping.
    retryOnStatuses: List[int]  # Default: 408, 425, 429, 500, 502, 503, 504.
    retryOnNetworkErrors: bool  # Retry a request that never produced a response (DNS, reset, timeout).
    respectRetryAfter: bool  # Honour a Retry-After header in preference to the computed backoff, bounded by initialDelayMs/maxDelayMs at both ends.
    methods: Optional[List[Literal['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']]]  # null (the default) means every method, but unsafe methods then retry ONLY on a failure proving the provider never acted (425/429) — a POST that 504s may already


